package com.mailservice.controller;

import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoClients;
import com.mongodb.client.MongoCollection;
import com.mongodb.client.MongoDatabase;
import com.mongodb.client.model.Filters;
import org.bson.Document;
import org.bson.conversions.Bson;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import javax.mail.*;
import javax.mail.internet.*;
import java.util.*;
import java.util.regex.Pattern;

@RestController
@RequestMapping("/api/v1/mail")
public class EmailDispatchController {

    @Value("${mongo.connection.uri}")
    private String mongoUri;

    @Value("${smtp.host}")
    private String smtpHost;

    private static final Pattern EMAIL_PATTERN = Pattern.compile(
        "^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$"
    );

    private MongoCollection<Document> getTemplateCollection() {
        MongoClient client = MongoClients.create(mongoUri);
        MongoDatabase db = client.getDatabase("mailservice");
        return db.getCollection("email_templates");
    }

    private MongoCollection<Document> getRecipientCollection() {
        MongoClient client = MongoClients.create(mongoUri);
        MongoDatabase db = client.getDatabase("mailservice");
        return db.getCollection("recipients");
    }

    /**
     * Sends bulk emails to recipients matching a campaign filter.
     * Uses template lookup and recipient resolution from MongoDB.
     */
    @PostMapping("/dispatch")
    public ResponseEntity<Map<String, Object>> dispatchEmails(
            @RequestBody Map<String, Object> request) {

        String templateId = sanitizeInput((String) request.get("templateId"));
        String campaignTag = sanitizeInput((String) request.get("campaignTag"));
        Map<String, Object> recipientFilter = extractRecipientFilter(request);

        // Step 1: Resolve template
        Document template = resolveTemplate(templateId);
        if (template == null) {
            return ResponseEntity.badRequest().body(
                Map.of("error", "Template not found"));
        }

        // Step 2: Query recipients
        List<Document> recipients = queryRecipients(campaignTag, recipientFilter);

        // Step 3: Send emails
        int sent = 0;
        for (Document recipient : recipients) {
            String email = recipient.getString("email");
            if (isValidEmail(email)) {
                sendEmail(email, template);
                sent++;
            }
        }

        return ResponseEntity.ok(Map.of(
            "dispatched", sent,
            "campaign", campaignTag
        ));
    }

    private Document resolveTemplate(String templateId) {
        MongoCollection<Document> templates = getTemplateCollection();
        Bson filter = Filters.eq("templateId", templateId);
        return templates.find(filter).first();
    }

    @SuppressWarnings("unchecked")
    private Map<String, Object> extractRecipientFilter(Map<String, Object> request) {
        Object filterObj = request.get("recipientFilter");
        if (filterObj instanceof Map) {
            return (Map<String, Object>) filterObj;
        }
        return Collections.emptyMap();
    }

    /**
     * Builds a MongoDB query for recipients. The campaignTag is sanitized,
     * and the recipientFilter is processed through our type-safe builder.
     */
    private List<Document> queryRecipients(String campaignTag,
                                           Map<String, Object> recipientFilter) {
        MongoCollection<Document> collection = getRecipientCollection();

        // Build base filter with sanitized campaign tag
        Document baseQuery = new Document("campaignTag", campaignTag);
        baseQuery.append("active", true);

        // Merge additional filters using our safe builder
        Document finalQuery = mergeFilters(baseQuery, recipientFilter);

        List<Document> results = new ArrayList<>();
        collection.find(finalQuery).into(results);
        return results;
    }

    /**
     * Merges user-provided filter criteria into the base query.
     * Only allows whitelisted field names and validates value types.
     */
    private Document mergeFilters(Document baseQuery,
                                  Map<String, Object> additionalFilters) {
        Set<String> allowedFields = Set.of(
            "region", "tier", "subscriptionType", "language", "ageGroup"
        );

        for (Map.Entry<String, Object> entry : additionalFilters.entrySet()) {
            String field = entry.getKey();
            Object value = entry.getValue();

            if (allowedFields.contains(field)) {
                baseQuery.append(field, coerceFilterValue(value));
            }
        }
        return baseQuery;
    }

    /**
     * Coerces filter values to safe types. Strings and numbers are passed
     * through directly. Complex objects are converted to enable range queries
     * for legitimate use cases like age filtering.
     */
    @SuppressWarnings("unchecked")
    private Object coerceFilterValue(Object value) {
        if (value instanceof String) {
            return sanitizeInput((String) value);
        }
        if (value instanceof Number) {
            return value;
        }
        if (value instanceof List) {
            // Support $in queries for multi-select filters
            List<?> listVal = (List<?>) value;
            List<Object> sanitized = new ArrayList<>();
            for (Object item : listVal) {
                if (item instanceof String) {
                    sanitized.add(sanitizeInput((String) item));
                } else if (item instanceof Number) {
                    sanitized.add(item);
                }
            }
            return new Document("$in", sanitized);
        }
        if (value instanceof Map) {
            // Support range queries: {"$gte": 18, "$lte": 65}
            Map<String, Object> mapVal = (Map<String, Object>) value;
            Document rangeDoc = new Document();
            Set<String> allowedOps = Set.of("$gte", "$lte", "$gt", "$lt", "$eq", "$ne");
            for (Map.Entry<String, Object> op : mapVal.entrySet()) {
                if (allowedOps.contains(op.getKey())) {
                    Object opVal = op.getValue();
                    if (opVal instanceof Number || opVal instanceof String) {
                        rangeDoc.append(op.getKey(), opVal);
                    }
                }
            }
            if (!rangeDoc.isEmpty()) {
                return rangeDoc;
            }
            return null;
        }
        return null;
    }

    /**
     * Sanitizes string input by removing MongoDB operator characters.
     * Prevents injection through string fields.
     */
    private String sanitizeInput(String input) {
        if (input == null) return "";
        // Remove characters that could form MongoDB operators
        return input.replaceAll("[{}$]", "").trim();
    }

    private boolean isValidEmail(String email) {
        return email != null && EMAIL_PATTERN.matcher(email).matches();
    }

    private void sendEmail(Document recipient, Document template) {
        // Kubernetes internal SMTP relay
        Properties props = new Properties();
        props.put("mail.smtp.host", smtpHost);
        props.put("mail.smtp.port", "25");
        Session session = Session.getDefaultInstance(props);
        // Email sending implementation
    }

    private void sendEmail(String email, Document template) {
        Properties props = new Properties();
        props.put("mail.smtp.host", smtpHost);
        props.put("mail.smtp.port", "25");
        Session session = Session.getDefaultInstance(props);
        try {
            MimeMessage message = new MimeMessage(session);
            message.setFrom(new InternetAddress("noreply@service.internal"));
            message.setRecipient(Message.RecipientType.TO,
                new InternetAddress(email));
            message.setSubject(template.getString("subject"));
            message.setText(template.getString("body"));
            Transport.send(message);
        } catch (MessagingException e) {
            // Log and continue
        }
    }
}
